public sealed record StudyItem(string Title, int Minutes, int Priority);

public static IReadOnlyList<string> TopStudyItems(IEnumerable<StudyItem> items)
{
    return items
        .Where(i => i.Priority >= 3)
        .OrderByDescending(i => i.Priority)
        .ThenBy(i => i.Minutes)
        .Take(3)
        .Select(i => i.Title)
        .ToList();
}
